/* --- Issue #526: the analog carrier, from dsp/analog_rx.c, which this fixture does not link: with no detector session
 * there is no generation to compare, so the published carrier stands as it is -- exactly what the real function
 * returns then. --- */
int
dsd_analog_rx_carrier_open_now(const dsd_opts* opts, const dsd_state* state) {
    return (opts && state && state->analog_rx.carrier_open) ? 1 : 0;
}

/* Issue #527, the same way: the published end of a rejected reception stands as it is while detection runs. */
int
dsd_analog_rx_rejection_ended_now(const dsd_opts* opts, const dsd_state* state) {
    return (opts && state && state->analog_rx.gate_rejected_ended && dsd_analog_tone_detection_active(opts)) ? 1 : 0;
}

/* The publication's stale deadline against the tap's clock, which outside tests is the real one: as the real function
   reads it. */
int
dsd_analog_rx_stale_now(const dsd_state* state) {
    return state && state->analog_rx.stale_after_ms != 0U && dsd_realtime_mono_ms() > state->analog_rx.stale_after_ms;
}

