static int
test_parser_rejects_invalid_inputs(void) {
    int rc = 0;
    rc |= expect_parser_rejects("duplicate-id", "a,p25-trunk,851000000,,,,\n"
                                                "a,dmr-trunk,852000000,,,,\n");
    rc |= expect_parser_rejects("duplicate-type-frequency", "a,p25-trunk,851000000,,,,\n"
                                                            "b,p25-trunk,851000000,,,,\n");
    rc |= expect_parser_rejects("invalid-type", "a,nxdn,851000000,,,,\n");
    rc |= expect_parser_rejects("invalid-frequency", "a,p25-trunk,0,,,,\n");
#if LONG_MAX < 4294967295LL
    rc |= expect_parser_rejects("frequency-long-overflow", "a,p25-trunk,2400000000,,,,\n");
#endif
    rc |= expect_parser_rejects("invalid-dwell", "a,p25-trunk,851000000,,249,,\n");
    rc |= expect_parser_rejects("conventional-chan-csv", "a,dmr-conventional,461000000,chan.csv,,,\n");
    rc |= expect_parser_rejects("p25-conventional-chan-csv", "a,p25-conventional,851500000,chan.csv,,,\n");
    rc |= expect_parser_rejects_with_header(
        "p25-conventional-bandplan", "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,p25_bandplan_csv\n",
        "a,p25-conventional,851500000,,,,,bandplan.csv\n");
    rc |= expect_parser_rejects_with_header(
        "p25-conventional-gfsk", "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation\n",
        "a,p25-conventional,851500000,,,,,gfsk\n");
    rc |= expect_parser_rejects_with_header(
        "duplicate-modulation-header",
        "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation,modulation\n",
        "a,p25-trunk,851000000,,,,,auto,c4fm\n");
    rc |= expect_parser_rejects_with_header(
        "invalid-modulation", "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation\n",
        "a,p25-trunk,851000000,,,,,wide\n");
    rc |= expect_parser_rejects_with_header(
        "unsupported-modulation", "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation\n",
        "a,dmr-trunk,452000000,,,,,cqpsk\n");
    rc |= expect_parser_rejects("nxdn-conventional-chan-csv", "a,nxdn-conventional,461000000,chan.csv,,,\n");
    rc |= expect_parser_rejects_with_header(
        "nxdn-unsupported-modulation", "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation\n",
        "a,nxdn-trunk,461000000,,,,,cqpsk\n");
    rc |= expect_parser_rejects("nxdn48-conventional-chan-csv", "a,nxdn48-conventional,461556250,chan.csv,,,\n");
    rc |= expect_parser_rejects_with_header(
        "nxdn48-unsupported-modulation", "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation\n",
        "a,nxdn48-conventional,461556250,,,,,c4fm\n");
    rc |=
        expect_parser_rejects_with_header("nxdn48-trunk-unsupported-modulation",
                                          "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation\n",
                                          "a,nxdn48-trunk,461556250,,,,,cqpsk\n");
    rc |= expect_parser_rejects_with_header("invalid-rtl-gain",
                                            "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,rtl_gain\n",
                                            "a,p25-trunk,851000000,,,,,50\n");
    return rc;
}

/* Issue #672: a target id is the target's name to the frontends, which carry it as text (Qt, JSON) and hand it back
   for put back; only valid UTF-8 survives that byte for byte. The loader refuses any other id and names its row (the
   header is row 1), and keeps a multibyte id -- a 4-byte character, a quote and a backslash among it -- as written. */
static int
test_parser_refuses_a_non_utf8_id(void) {
    static const char* const k_bad[] = {
        "caf\xE9",           /* Latin-1 */
        "a\xC0\xAF",         /* overlong '/' */
        "a\xED\xA0\x80",     /* a surrogate */
        "a\xF4\x90\x80\x80", /* above U+10FFFF */
        "a\xE2\x82",         /* cut short */
    };
    int rc = 0;
    for (size_t i = 0; i < sizeof k_bad / sizeof k_bad[0] && rc == 0; i++) {
        char dir[DSD_TEST_PATH_MAX];
        char target_path[DSD_TEST_PATH_MAX];
        char body[256];
        DSD_SNPRINTF(body, sizeof body, "ok,p25-trunk,851000000,,,,\n%s,dmr-trunk,452000000,,,,\n", k_bad[i]);
        if (make_temp_dir(dir, sizeof dir) != 0) {
            return 1;
        }
        if (write_targets_file(dir, body, target_path, sizeof target_path) != 0) {
            cleanup_paths(dir, NULL, NULL);
            return 1;
        }
        static dsd_opts opts;
        DSD_MEMSET(&opts, 0, sizeof opts);
        dsd_trunk_scan_target_list list;
        DSD_MEMSET(&list, 0, sizeof list);
        char err[256] = {0};
        if (dsd_trunk_scan_load_targets_csv(target_path, &opts, &list, err, sizeof err) == 0) {
            DSD_FPRINTF(stderr, "non-UTF-8 id %zu was accepted\n", i);
            rc = 1;
        } else if (strstr(err, "row 3") == NULL || strstr(err, "UTF-8") == NULL) {
            DSD_FPRINTF(stderr, "non-UTF-8 id %zu: unexpected error '%s'\n", i, err);
            rc = 1;
        }
        dsd_trunk_scan_target_list_reset(&list);
        cleanup_paths(dir, target_path, NULL);
    }
    if (rc != 0) {
        return rc;
    }

    static const char k_good[] = "\"caf\xC3\xA9 \xF0\x9F\x93\xA1 \\ q\"\"\"";
    static const char k_good_id[] = "caf\xC3\xA9 \xF0\x9F\x93\xA1 \\ q\"\"";
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    char body[256];
    DSD_SNPRINTF(body, sizeof body, "%s,p25-trunk,851000000,,,,\n", k_good);
    if (make_temp_dir(dir, sizeof dir) != 0) {
        return 1;
    }
    if (write_targets_file(dir, body, target_path, sizeof target_path) != 0) {
        cleanup_paths(dir, NULL, NULL);
        return 1;
    }
    static dsd_opts opts;
    DSD_MEMSET(&opts, 0, sizeof opts);
    dsd_trunk_scan_target_list list;
    DSD_MEMSET(&list, 0, sizeof list);
    char err[256] = {0};
    if (dsd_trunk_scan_load_targets_csv(target_path, &opts, &list, err, sizeof err) != 0 || list.count != 1U
        || strcmp(list.targets[0].id, k_good_id) != 0) {
        DSD_FPRINTF(stderr, "a UTF-8 id did not load as written: '%s'\n", err);
        rc = 1;
    }
    dsd_trunk_scan_target_list_reset(&list);
    cleanup_paths(dir, target_path, NULL);
    return rc;
}

static int
test_parser_accepts_100_targets(void) {
    char dir[DSD_TEST_PATH_MAX];
    if (make_temp_dir(dir, sizeof dir) != 0) {
        return 1;
    }
    char body[8192];
    body[0] = '\0';
    for (int i = 0; i < 100; i++) {
        char row[128];
        DSD_SNPRINTF(row, sizeof row, "id%d,dmr-conventional,%u,,,,,%u\n", i, 461000000U + (unsigned)i, (unsigned)i);
        if (append_text(body, sizeof body, row) != 0) {
            cleanup_paths(dir, NULL, NULL);
            return 1;
        }
    }
    char target_path[DSD_TEST_PATH_MAX];
    static const char header[] = "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,single_key_dec\n";
    if (write_targets_file_with_header(dir, header, body, target_path, sizeof target_path) != 0) {
        cleanup_paths(dir, NULL, NULL);
        return 1;
    }

    static dsd_opts opts;
    DSD_MEMSET(&opts, 0, sizeof opts);
    opts.trunk_scan_idle_dwell_ms = 3000;
    opts.trunk_scan_activity_hold_ms = 1200;
    dsd_trunk_scan_target_list list;
    DSD_MEMSET(&list, 0, sizeof list);
    char err[256] = {0};
    int rc = dsd_trunk_scan_load_targets_csv(target_path, &opts, &list, err, sizeof err);
    int test_rc = 0;
    if (rc != 0 || list.count != 100 || list.targets == NULL || strcmp(list.targets[99].id, "id99") != 0
        || list.targets[99].frequency_hz != 461000099U || list.targets[99].dwell_ms != 3000
        || list.targets[99].activity_hold_ms != 1200 || list.targets[0].single_keys_present != 1U
        || list.targets[0].single_key_scalars.K != 0ULL || list.targets[99].single_keys_present != 1U
        || list.targets[99].single_key_scalars.K != 99ULL) {
        DSD_FPRINTF(stderr, "parser 100 targets rc=%d count=%zu err=%s\n", rc, list.count, err);
        test_rc = 1;
    }
    dsd_trunk_scan_target_list_reset(&list);
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
make_runtime_targets(const char* body, char* out_path, size_t out_sz, char* out_dir, size_t out_dir_sz) {
    if (make_temp_dir(out_dir, out_dir_sz) != 0) {
        return -1;
    }
    return write_targets_file(out_dir, body, out_path, out_sz);
}

/* One options and state pair on the heap that the issue #890 cases reuse in turn (allocated in main()): each case
   resets it as it starts (reset_scan_opts_state()), so none keeps a 2 MB state of its own for the whole run. */
static dsd_opts* g_case_opts = NULL;
static dsd_state* g_case_state = NULL;

static void
reset_scan_opts_state(dsd_opts* opts, dsd_state* state) {
    dsd_state_ext_free_all(state);
    dsd_state_trunk_lcn_free(state);
    dsd_state_trunk_scan_avoids_free(state);
    DSD_MEMSET(opts, 0, sizeof(*opts));
    DSD_MEMSET(state, 0, sizeof(*state));
    opts->trunk_scan_enabled = 1;
    opts->trunk_scan_idle_dwell_ms = 250;
    opts->trunk_scan_activity_hold_ms = 250;
    opts->audio_in_type = AUDIO_IN_RTL;
    opts->rtl_dsp_bw_khz = 48;
    opts->rigctl_sockfd = DSD_INVALID_SOCKET;
    opts->trunk_tune_group_calls = 1;
    opts->trunk_tune_private_calls = 1;
    opts->trunk_tune_enc_calls = 1;
    state->rtl_ctx = (struct RtlSdrContext*)state;
    state->dmr_mfid = -1;
    state->dmr_color_code = 16;
    state->dmr_confidence_color_code = 16;
    state->dmr_confidence_candidate_cc = 16;
    g_p25_tick_guard_available = 1;
    g_p25_tick_guard_depth = 0;
    g_p25_tick_guard_enter_calls = 0;
    g_p25_tick_guard_leave_calls = 0;
    g_fake_rtl_output_rate_hz = 0;
    dsd_rtl_stream_metrics_hooks_set(NULL);
}

/* The patch table's freshness travels with the target (its listening clock, stamps, recency and owner), as do
   entries and members past the old 8x8 table. */
static void
seed_p25_patch_freshness(dsd_state* state, double clock_s, uint32_t base) {
    state->p25_patch_listen_s = clock_s;
    state->p25_patch_listen_last_m = 42.0;
    state->p25_patch_seen_listen_s[0] = clock_s - 1.0;
    state->p25_patch_members_listen_s[0] = clock_s - 2.0;
    state->p25_patch_seq[0] = base;
    state->p25_patch_seq_counter = base + 1U;
    state->p25_patch_owner_known = 1;
    state->p25_patch_owner_wacn = base + 2U;
    state->p25_patch_owner_sysid = (uint16_t)(base + 3U);
    state->p25_patch_sgid[DSD_P25_PATCH_MAX - 1] = (uint16_t)(base + 4U);
    state->p25_patch_wgid[DSD_P25_PATCH_MAX - 1][DSD_P25_PATCH_GROUP_MAX - 1] = (uint16_t)(base + 5U);
    state->p25_patch_wuid[DSD_P25_PATCH_MAX - 1][DSD_P25_PATCH_RADIO_MAX - 1] = base + 6U;
}

static int
expect_p25_patch_freshness(const dsd_state* state, double clock_s, uint32_t base) {
    if (fabs(state->p25_patch_listen_s - clock_s) > 1e-9 || fabs(state->p25_patch_listen_last_m) > 1e-9
        || fabs(state->p25_patch_seen_listen_s[0] - (clock_s - 1.0)) > 1e-9
        || fabs(state->p25_patch_members_listen_s[0] - (clock_s - 2.0)) > 1e-9 || state->p25_patch_seq[0] != base
        || state->p25_patch_seq_counter != base + 1U || state->p25_patch_owner_known != 1
        || state->p25_patch_owner_wacn != base + 2U || state->p25_patch_owner_sysid != (uint16_t)(base + 3U)
        || state->p25_patch_sgid[DSD_P25_PATCH_MAX - 1] != (uint16_t)(base + 4U)
        || state->p25_patch_wgid[DSD_P25_PATCH_MAX - 1][DSD_P25_PATCH_GROUP_MAX - 1] != (uint16_t)(base + 5U)
        || state->p25_patch_wuid[DSD_P25_PATCH_MAX - 1][DSD_P25_PATCH_RADIO_MAX - 1] != base + 6U) {
        DSD_FPRINTF(stderr, "P25 patch freshness/owner state leaked across scan targets\n");
        return 1;
    }
    return 0;
}

