/* The close of the recordings no call owns, which a target switch runs as it leaves the carrier (issue #809 B4):
   counted. CORE_WAV_JOURNAL runs the real one through the real switch. */
void
dsd_event_flush_orphan_recordings(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    (void)state;
    g_orphan_flush_calls++;
}

/* The digital voice level, which a target switch starts over for the incoming carrier (issue #518): counted, both
   slots at once. */
void
dsd_voice_level_reset(dsd_state* state, int slot) {
    (void)state;
    if (slot < 0) {
        g_voice_level_resets++;
    }
}

/* What the decoders gathered on a carrier, which a target switch forgets (issue #575): counted, with a stand-in
   assembly the real function drops (an NXDN SACCH superframe's part). */
void
dsd_engine_forget_carrier_decoding(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    g_forget_carrier_decoding_calls++;
    pause_log("forget");
    state->nxdn_part_of_frame = 0;
    state->dmr_le_vendor[0] = DMR_LE_VENDOR_NONE;
    state->dmr_le_vendor[1] = DMR_LE_VENDOR_NONE;
}

/* From protocol/dmr/dmr_enc_class.c, which this fixture does not link: the fields a target visit's restore must not
   bring back (the service options, the vendor and pre-call PI evidence) and the slots' autoload talkgroups. */
void
dmr_forget_call_privacy(dsd_state* state) {
    state->dmr_so = state->dmr_soR = 0U;
    state->dmr_fid = state->dmr_fidR = 0U;
    for (int idx = 0; idx < 2; idx++) {
        state->dmr_le_vendor[idx] = DMR_LE_VENDOR_NONE;
        state->dmr_pi_precall_rx[idx] = 0U;
        state->dmr_pi_precall_algid[idx] = 0U;
        state->dmr_pi_precall_kid[idx] = 0U;
        state->dmr_pi_precall_m[idx] = 0.0;
        state->dmr_crypto_inherited[idx] = 0U;
        state->dmr_tg_autoload.slot_tg[idx] = 0U;
    }
}

/* From the same source: a target visit holds each slot's voice until its call says whether it is encrypted. */
void
dmr_enc_class_hold(dsd_state* state) {
    state->dmr_enc_class_held[0] = state->dmr_enc_class_held[1] = 1U;
}

/* Coordinator tests stub DSP; acquisition contents are covered by FRAME_SYNC_INTERNAL_HELPERS.
   The received-tone reset is mirrored from the real function (issue #522), so a switch that
   stopped calling it, or restored a target's tone after it, shows up here. */
/* dsd_frame_sync_p25p1_learned_rf_mod() is the real one (src/dsp/frame_sync_p25p1_compare.c), which arms the CQPSK
 * dwell through this (frame_sync_internal.h) when a tune ends a comparison. */
void
frame_sync_qpsk_dwell_set(int armed) {
    (void)armed;
}

/* ... and puts the decoder back on a tuned chain through this when it reconciles a watchdog tune. */
void
frame_sync_p25p1_set_chain(const dsd_opts* opts, dsd_state* state, int chain) {
    (void)opts;
    state->rf_mod = chain;
}

void
dsd_frame_sync_reset_acquisition(const dsd_opts* opts, dsd_state* state, int forget) {
    (void)forget;
    /* As the real reset's chain step does: a watchdog tune's notice still pending is reconciled first. */
    (void)dsd_frame_sync_apply_off_thread_tunes(opts, state);
    state->profile_proof_valid = 0;
    state->sps_hunt_counter = 0;
    /* As the real reset does: a P25p1 chain comparison in flight ends, with no verdict and nothing restored. */
    state->p25_p1_mod_compare.phase = 0;
    state->p25_p1_mod_probe_active = 0;
    const uint32_t generation = state->analog_rx.generation + 1U;
    DSD_MEMSET(&state->analog_rx, 0, sizeof(state->analog_rx));
    state->analog_rx.generation = generation;
}

/* The channel-scan leave's analog monitor block drop; covered by ENGINE_CHANNEL_SCAN and APP_COMMAND_QUEUE. */
void
dsd_symbol_analog_block_reset(dsd_state* state) {
    (void)state;
}
